CREATE OR REPLACE FUNCTION public.appearance_decide(p_id uuid, p_expected_version integer, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;p zoi.artist_appearances;prior zoi.artist_appearances;ar boolean;er boolean;
begin actor:=zoi.trip_actor();select * into prior from zoi.artist_appearances where id=p_id;if prior.id is null then raise exception 'appearance_unavailable';end if;
 perform 1 from zoi.listings where id in(prior.artist_id,prior.event_id) order by id for share;
 ar:=coalesce(zoi.ops_role(prior.artist_workspace),'') in('owner','admin');er:=coalesce(zoi.ops_role(prior.event_workspace),'') in('owner','admin');if not ar and not er then raise exception 'appearance_permission_denied' using errcode='42501';end if;
 select * into prior from zoi.artist_appearances where id=p_id for update;if prior.version is distinct from p_expected_version then raise exception 'appearance_version_conflict';end if;
 if prior.status='withdrawn' or p_action not in('confirm','withdraw') or p_action is null then raise exception 'appearance_transition_invalid';end if;
 if p_action='confirm' and not zoi.appearance_current(prior) then raise exception 'appearance_listing_unavailable';end if;
 update zoi.artist_appearances set artist_confirmed_by=case when p_action='confirm' and ar then actor else artist_confirmed_by end,event_confirmed_by=case when p_action='confirm' and er then actor else event_confirmed_by end,status=case when p_action='withdraw' then 'withdrawn' when (ar or artist_confirmed_by is not null) and (er or event_confirmed_by is not null) then 'confirmed' else 'pending' end,version=version+1,updated_at=clock_timestamp() where id=p_id returning * into p;
 insert into zoi.appearance_audit(appearance_id,actor_id,action,before_state,after_state) values(p.id,actor,p_action,to_jsonb(prior),to_jsonb(p));return jsonb_build_object('ok',true,'appearance',to_jsonb(p));end $function$

CREATE OR REPLACE FUNCTION public.time_entry_transition(p_workspace uuid, p_entry uuid, p_expected_version integer, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;admin boolean;prior zoi.time_entries;e zoi.time_entries;new_status text;
begin
 actor:=zoi.time_actor(p_workspace);admin:=zoi.ops_role(p_workspace) in('owner','admin');
 select * into prior from zoi.time_entries where id=p_entry and workspace_id=p_workspace for update;
 if prior.id is null or (prior.profile_id<>actor and not admin) then raise exception 'time_permission_denied' using errcode='42501';end if;
 if prior.version is distinct from p_expected_version then raise exception 'time_version_conflict';end if;
 if p_action='submit' and prior.profile_id=actor and prior.status in('draft','returned') then new_status:='submitted';
 elsif p_action='withdraw' and prior.profile_id=actor and prior.status='submitted' then new_status:='draft';
 elsif p_action='approve' and admin and prior.status='submitted' then new_status:='approved';
 elsif p_action='return' and admin and prior.status='submitted' then new_status:='returned';
 elsif p_action='void' and ((admin and prior.status='approved') or (prior.profile_id=actor and prior.status in('draft','returned'))) then new_status:='voided';
 else raise exception 'time_transition_not_allowed';end if;
 if length(coalesce(p_reason,''))>1000 or (p_action in('return','void') and btrim(coalesce(p_reason,''))='') then raise exception 'time_reason_required';end if;
 update zoi.time_entries set status=new_status,version=version+1,approved_by=case when new_status='approved' then actor else approved_by end,approved_at=case when new_status='approved' then clock_timestamp() else approved_at end,updated_at=clock_timestamp() where id=prior.id returning * into e;
 insert into zoi.time_audit(workspace_id,entry_id,actor_id,action,reason,before_state,after_state) values(p_workspace,e.id,actor,p_action,coalesce(p_reason,''),to_jsonb(prior),to_jsonb(e));
 return jsonb_build_object('ok',true,'entry',to_jsonb(e));
end $function$

